 import unittest
from candidate import all_prefixes

class TestAllPrefixes(unittest.TestCase):
    def test_all_prefixes_empty_string(self):
        self.assertEqual(all_prefixes(''), [])

    def test_all_prefixes_single_character(self):
        self.assertEqual(all_prefixes('a'), ['a'])

    def test_all_prefixes_multiple_characters(self):
        self.assertEqual(all_prefixes('abc'), ['a', 'ab', 'abc'])

    def test_all_prefixes_single_character_repeated(self):
        self.assertEqual(all_prefixes('aa'), ['a', 'aa'])

    def test_all_prefixes_string_with_digits(self):
        self.assertEqual(all_prefixes('123'), ['1', '12', '123'])

    def test_all_prefixes_string_with_special_characters(self):
        self.assertEqual(all_prefixes('ab!c'), ['a', 'ab', 'ab!', 'ab!c'])

    def test_all_prefixes_string_with_mix_of_characters(self):
        self.assertEqual(all_prefixes('1aB!c'), ['1', '1a', '1aB', '1aB!', '1aB!c'])

if __name__ == '__main__':
    unittest.main()
